{
  "questions": [
    {
      "question_id": "q1",
      "question": "What does the petroleum liquid look like at the proposed measurement point?"
    },
    {
      "question_id": "q2",
      "question": "What are the cable route and length to the analyzer in the other building, and could an analyzer or sensor be installed near the process?"
    },
    {
      "question_id": "q3",
      "question": "Is the water-content measurement intended for research, a pilot line or production?"
    },
    {
      "question_id": "q4",
      "question": "Is there a reference method that can provide comparison values for water content?"
    },
    {
      "question_id": "q5",
      "question": "Do you already have numerical acceptance criteria, such as accuracy or a detection limit?"
    },
    {
      "question_id": "q6",
      "question": "Over what range must water content be followed?"
    }
  ],
  "plan": {
    "objective": "Screen candidate methods on retained petroleum samples for water-content measurement against client-agreed criteria.",
    "samples_and_states": [
      {
        "text": "Select retained samples spanning the agreed water-content range and relevant liquid states.",
        "claim_type": "PROPOSAL",
        "evidence_ids": []
      }
    ],
    "reference_measurements": [
      {
        "text": "Obtain independent water-content reference values for the test samples using a reference method agreed with the client.",
        "claim_type": "PROPOSAL",
        "evidence_ids": []
      }
    ],
    "setup": [
      {
        "text": "Confirm the MIR ATR trial’s optical link with AFS, excluding the existing silica cable.",
        "claim_type": "PROPOSAL",
        "evidence_ids": []
      }
    ],
    "comparison": [
      {
        "text": "Compare each candidate method separately with the reference values using criteria agreed with the client before testing.",
        "claim_type": "PROPOSAL",
        "evidence_ids": []
      }
    ],
    "validation": [
      {
        "text": "Validate the screened methods on independent petroleum samples withheld from method development.",
        "claim_type": "PROPOSAL",
        "evidence_ids": []
      }
    ],
    "go_no_go": [
      {
        "text": "Make further engineering conditional on meeting the agreed validation criteria and AFS confirming the proposed optical link.",
        "claim_type": "PROPOSAL",
        "evidence_ids": []
      }
    ],
    "not_demonstrated": [
      {
        "text": "Routine performance of the proposed remote MIR ATR installation remains unestablished.",
        "claim_type": "UNKNOWN",
        "evidence_ids": []
      }
    ],
    "steps": [
      "Clarify liquid appearance, routing, intended use, range and acceptance criteria.",
      "Select representative retained samples and relevant liquid states.",
      "Obtain independent water-content reference values.",
      "Confirm the setup and compare candidate methods separately.",
      "Validate against agreed criteria on independent samples.",
      "Decide go or no-go, including optical-link feasibility."
    ]
  },
  "decision_basis": [
    {
      "text": "Base the decision on comparison with reference water-content values on independent petroleum samples against client-agreed criteria set before testing.",
      "claim_type": "PROPOSAL",
      "evidence_ids": []
    }
  ]
}
